def classify_vuln_category(vuln_class: str) -> str:
    clean = vuln_class.upper().strip()
    if clean in VULN_CATEGORY_MAP:
        return VULN_CATEGORY_MAP[clean]
    
    # Heuristics
    if any(term in clean for term in ["REENTRAN", "ORACLE", "DELEGATECALL", "INFLAT", "UPGRADE", "SUICID"]):
        return CATEGORY_SECURITY
    if any(term in clean for term in ["CAST", "UNCHECKED", "FEE", "TRANSFER", "ZERO_ADDRESS", "RETURN"]):
        return CATEGORY_CORRECTNESS
    if any(term in clean for term in ["GAS", "PUSH0", "IMMUTABLE", "CONST"]):
        return CATEGORY_GAS
    if any(term in clean for term in ["PRAGMA", "SOLC", "EVENT", "LOW_LEVEL"]):
        return CATEGORY_INFORMATIONAL
    
    return CATEGORY_QUALITY


def is_proxy_template_mechanic(vuln_class: str, canonical_loc: str, contract_role: str = "") -> bool:
    """Detects when an assembly or locked-ether alert is just standard proxy machinery."""
    loc_lower = canonical_loc.lower()
    v_upper = vuln_class.upper()
    
    # Assembly or locks ether inside standard Proxy/UpgradeabilityProxy is intended design
    if any(term in loc_lower for term in ["proxy", "upgradeability", "erc1967", "fallback"]):
        if v_upper in ["ASSEMBLY", "CONTRACT_LOCKS_ETHER", "LOCKED_ETHER", "YUL_RETURN", "CONSTANT_FUNCTION_ASM"]:
            return True
        if "PROXY" in contract_role.upper():
            if v_upper in ["CONTRACT_LOCKS_ETHER", "LOCKED_ETHER", "ASSEMBLY"]:
                return True
    return False


def is_known_dependency(file_or_loc: str) -> bool:
    for pattern in KNOWN_DEPENDENCY_PATTERNS:
        if re.search(pattern, file_or_loc, re.IGNORECASE):
            return True
    return False


def calculate_finding_id(code_hash: str, canonical_loc: str, vuln_class: str) -> str:
    return calculate_semantic_finding_id(code_hash, canonical_loc, vuln_class)

def calculate_semantic_finding_id(code_hash: str, canonical_loc: str, vuln_class: str) -> str:
    """
    Deduplicates by semantic source location rather than just raw line numbers.
    e.g. Contract.sol:L142 and Contract.withdraw() map to the same semantic root.
    """
    # Normalize function and contract
    norm_loc = canonical_loc.strip().lower()
    norm_loc = re.sub(r":l\\d+", "", norm_loc) # Strip line number (:L123)
    norm_loc = re.sub(r"\(.*?\)", "", norm_loc) # Strip parameter parentheses

    norm_vuln = vuln_class.strip().upper()
    key = f"{code_hash}:{norm_loc}:{norm_vuln}".encode("utf-8")
    return hashlib.sha256(key).hexdigest()[:32]


@dataclass
class NormalizedFinding:
    finding_id: str
    code_hash: str
    vuln_class: str
    canonical_location: str
    normalized_severity: str = "low"              # critical, high, medium, low, informational
    confidence_score: float = 0.5
    category: str = "quality"                     # security, correctness, quality, gas, informational
    workflow_stage: str = "CODE_QUALITY"          # CONFIRMED_EXPLOIT, PROBABLE_SECURITY_ISSUE, NEEDS_REVIEW, CODE_QUALITY
    is_corroborated: bool = False                 # True if >= 2 distinct engines agree
    attestations: List[EngineAttestation] = field(default_factory=list)
    is_suppressed: bool = False
    suppression_reason: Optional[str] = None
    is_dependency_finding: bool = False


class Aggregator:
    def __init__(
        self,
        active_suppressions: Optional[List[Dict[str, Any]]] = None,
        suppress_quality_and_gas_by_default: bool = True
    ):
        self.suppressions = active_suppressions or []
        self.suppress_noise = suppress_quality_and_gas_by_default

    def aggregate_results(
        self,
        code_hash: str,
        job_results: List[JobResult],
        contract_role: str = ""
    ) -> List[NormalizedFinding]:
        """Groups raw attestations into semantic clusters, applies penalties, and categorizes workflow stages."""
        findings_map: Dict[str, List[EngineAttestation]] = {}

        for job in job_results:
            for attestation in job.findings:
                f_id = calculate_semantic_finding_id(code_hash, attestation.canonical_location, attestation.vuln_class)
                findings_map.setdefault(f_id, []).append(attestation)

