from pathlib import Path
import json

def find_slither_target(dir_path: Path, contract_name: str = None) -> str:
    if (dir_path / "src").is_dir():
        return "src"
    if (dir_path / "contracts").is_dir():
        return "contracts"
    root_sols = list(dir_path.glob("*.sol"))
    if root_sols:
        return "."
    if contract_name:
        for f in dir_path.rglob(f"{contract_name}.sol"):
            return str(f.relative_to(dir_path))
    for f in dir_path.rglob("*.sol"):
        rel = str(f.relative_to(dir_path))
        if not rel.startswith("lib/") and not rel.startswith("node_modules/"):
            return str(f.parent.relative_to(dir_path))
    # fallback to any sol file parent
    all_sols = list(dir_path.rglob("*.sol"))
    if all_sols:
        return str(all_sols[0].relative_to(dir_path))
    return "."

