def normalize_vuln_class(raw_rule_id: str) -> str:
    """Maps vendor-specific detector names to unified industry vulnerability categories."""
    clean_id = raw_rule_id.lower().strip()
    if clean_id in VULN_TAXONOMY_MAP:
        return VULN_TAXONOMY_MAP[clean_id]

    # Heuristic normalization
    if "reentran" in clean_id:
        return "REENTRANCY_EVENTS" if "event" in clean_id else "REENTRANCY"
    if "uninitialized" in clean_id and "state" in clean_id:
        return "UNINITIALIZED_STATE_VARIABLE"
    if "zero" in clean_id and "check" in clean_id:
        return "MISSING_ZERO_ADDRESS_CHECK"
    if "unchecked" in clean_id and "transfer" in clean_id:
        return "UNCHECKED_TRANSFER"
    if "unchecked" in clean_id and "return" in clean_id:
        return "UNCHECKED_RETURN"
    if "unindexed" in clean_id:
        return "UNINDEXED_EVENTS"
    if "pragma" in clean_id:
        return "UNSPECIFIC_PRAGMA"

    return clean_id.upper().replace("-", "_")


def get_solidity_scope(file_path: Path, target_line: int) -> Tuple[str, str, Tuple[int, int]]:
    """Identifies the enclosing contract and function for a given source line in Solidity."""
    if not file_path.exists():
        return "", "", (0, 0)
    try:
        lines = file_path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except Exception:
        return "", "", (0, 0)

    current_contract = ""
    current_func = ""
    curr_func_start = 0
    brace_depth = 0
    contract_brace_depth = -1
    func_brace_depth = -1
    pending_func = ""
    pending_func_start = 0

    contract_re = re.compile(r'\b(?:contract|library|interface)\s+([A-Za-z0-9_]+)')
    func_re = re.compile(r'\b(?:function|constructor|fallback|receive)\s+([A-Za-z0-9_]*)')

    for idx, line in enumerate(lines, 1):
        cleaned = re.sub(r'//.*$', '', line)
        cleaned = re.sub(r'\"[^\"]*\"', '\"\"', cleaned)
        cleaned = re.sub(r'\'[^\']*\'', '\'\'', cleaned)

        c_match = contract_re.search(cleaned)
        if c_match and contract_brace_depth == -1:
            current_contract = c_match.group(1)

        f_match = func_re.search(cleaned)
        if f_match and func_brace_depth == -1:
            pending_func = f_match.group(1) or ("constructor" if "constructor" in cleaned else "fallback")
            pending_func_start = idx

        for ch in cleaned:
            if ch == '{':
                brace_depth += 1
                if current_contract and contract_brace_depth == -1:
                    contract_brace_depth = brace_depth
                if pending_func and func_brace_depth == -1:
                    current_func = pending_func
                    curr_func_start = pending_func_start
                    func_brace_depth = brace_depth
                    pending_func = ""
            elif ch == ';':
                if pending_func and func_brace_depth == -1:
                    pending_func = ""
            elif ch == '}':
                if brace_depth == func_brace_depth:
                    if curr_func_start <= target_line <= idx:
                        return current_contract, current_func, (curr_func_start, idx)
                    current_func = ""
                    func_brace_depth = -1
                if brace_depth == contract_brace_depth:
                    current_contract = ""
                    contract_brace_depth = -1
                brace_depth -= 1

        if idx == target_line and current_func:
            return current_contract, current_func, (curr_func_start, idx)

    return current_contract, current_func, (curr_func_start, len(lines))


def find_native_solc() -> Optional[str]:
    """Finds an installed solc binary from svm-rs or PATH."""
    svm_dir = Path(os.path.expanduser("~/.svm"))
    if svm_dir.exists():
        solc_bins = sorted(svm_dir.glob("*/solc-*"), reverse=True)
        if solc_bins:
            return str(solc_bins[0])
    return shutil.which("solc")


