import re
from pathlib import Path

RESERVED_SOL_KEYWORDS = {
    "for", "if", "else", "while", "do", "break", "continue", "return", "returns",
    "try", "catch", "throw", "revert", "require", "assert", "emit",
    "public", "private", "internal", "external", "pure", "view", "payable",
    "virtual", "override", "modifier", "event", "struct", "enum", "mapping",
    "memory", "storage", "calldata", "is", "as", "new", "delete", "assembly", "with"
}

def get_solidity_scope_fixed(file_path: Path, target_line: int):
    if not file_path.exists():
        return "", "", (0, 0)
    try:
        content = file_path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return "", "", (0, 0)

    # Strip block comments first while preserving line count
    def comment_replacer(match):
        return "\n" * match.group(0).count("\n")
    cleaned_content = re.sub(r'/\*.*?\*/', comment_replacer, content, flags=re.DOTALL)
    lines = cleaned_content.splitlines()

    current_contract = ""
    current_func = ""
    curr_func_start = 0
    brace_depth = 0
    contract_brace_depth = -1
    func_brace_depth = -1
    pending_func = ""
    pending_func_start = 0

    contract_re = re.compile(r'\b(?:contract|library|interface)\s+([A-Za-z0-9_]+)')
    func_re = re.compile(r'\b(?:function|constructor|fallback|receive)\s*(?:([A-Za-z0-9_]+)\s*)?\(')

    target_contract = ""
    target_func = ""
    target_range = (target_line, target_line)

    for idx, line in enumerate(lines, 1):
        cleaned = re.sub(r'//.*$', '', line)
        cleaned = re.sub(r'\"[^\"]*\"', '\"\"', cleaned)
        cleaned = re.sub(r'\'[^\']*\'', '\'\'', cleaned)

        c_match = contract_re.search(cleaned)
        if c_match and contract_brace_depth == -1:
            current_contract = c_match.group(1)

        f_match = func_re.search(cleaned)
        if f_match and func_brace_depth == -1:
            name = f_match.group(1)
            # Constructor, fallback, receive
            if not name:
                for kw in ["constructor", "fallback", "receive"]:
                    if kw in cleaned:
                        name = kw
                        break
            if name and name.lower() not in RESERVED_SOL_KEYWORDS:
                pending_func = name
                pending_func_start = idx

        for ch in cleaned:
            if ch == '{':
                brace_depth += 1
                if current_contract and contract_brace_depth == -1:
                    contract_brace_depth = brace_depth
                if pending_func and func_brace_depth == -1:
                    current_func = pending_func
                    curr_func_start = pending_func_start
                    func_brace_depth = brace_depth
                    pending_func = ""
            elif ch == ';':
                if pending_func and func_brace_depth == -1:
                    pending_func = ""
            elif ch == '}':
                if brace_depth == func_brace_depth:
                    if curr_func_start <= target_line <= idx:
                        target_contract = current_contract
                        target_func = current_func
                        target_range = (curr_func_start, idx)
                    current_func = ""
                    func_brace_depth = -1
                if brace_depth == contract_brace_depth:
                    current_contract = ""
                    contract_brace_depth = -1
                brace_depth -= 1

        if idx == target_line:
            target_contract = current_contract
            if current_func:
                target_func = current_func
                target_range = (curr_func_start, target_line)
            else:
                target_func = ""
                target_range = (target_line, target_line)

    return target_contract, target_func, target_range

