    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256);
    function redeem(uint256 shares, address receiver, address owner) external returns (uint256);
}}

contract VaultHandler is Test {{
    IERC4626 public immutable vault;
    IERC20 public immutable asset;

    // Distinct multi-actor pool
    address public immutable actorUserA = address(0xAA1);
    address public immutable actorUserB = address(0xBB2);
    address public immutable actorAttacker = address(0x1337);
    address[3] public actors;

    // Ghost accounting & telemetry
    mapping(address => uint256) public ghost_deposited_assets;
    mapping(address => uint256) public ghost_shares_minted;
    mapping(address => uint256) public ghost_redeemed_assets;
    uint256 public ghost_attacker_initial_assets;
    uint256 public ghost_total_donations;
    uint256 public ghost_zero_share_deposits_count;

    // Execution quality metrics
    uint256 public successful_state_changes;
    uint256 public total_calls_attempted;
    uint256 public sequence_depth;
    mapping(bytes4 => uint256) public calls_by_selector;
    mapping(bytes4 => uint256) public reverts_by_selector;

    constructor(address _vault, address _asset) {{
        vault = IERC4626(_vault);
        asset = IERC20(_asset);
        actors = [actorUserA, actorUserB, actorAttacker];

        // Seed actors with initial funds
        for (uint256 i = 0; i < actors.length; i++) {{
