    }}

    function _selectActor(uint256 seed) internal view returns (address) {{
        return actors[seed % actors.length];
    }}

    function deposit(uint256 actorSeed, uint256 amount) external {{
        total_calls_attempted++;
        sequence_depth++;
        address actor = _selectActor(actorSeed);
        amount = bound(amount, 1 wei, 10_000 ether);

        vm.prank(actor);
        try vault.deposit(amount, actor) returns (uint256 shares) {{
            calls_by_selector[vault.deposit.selector]++;
            successful_state_changes++;
            ghost_deposited_assets[actor] += amount;
            ghost_shares_minted[actor] += shares;

            if (shares == 0 && amount > 0) {{
                ghost_zero_share_deposits_count++;
            }}
        }} catch {{
            reverts_by_selector[vault.deposit.selector]++;
        }}
    }}

    function mint(uint256 actorSeed, uint256 shares) external {{
        total_calls_attempted++;
        sequence_depth++;
        address actor = _selectActor(actorSeed);
        shares = bound(shares, 1 wei, 10_000 ether);

