            ghost_total_donations += amount;
        }} else {{
            reverts_by_selector[bytes4(keccak256("transfer(address,uint256)"))]++;
        }}
    }}

    function advanceTime(uint256 secondsPassed) external {{
        secondsPassed = bound(secondsPassed, 1, 30 days);
        skip(secondsPassed);
    }}

    function getMetrics() external view returns (
        uint256 totalAttempted,
        uint256 successfulChanges,
        uint256 depthReached,
        uint256 zeroShareDeposits
    ) {{
        return (total_calls_attempted, successful_state_changes, sequence_depth, ghost_zero_share_deposits_count);
    }}
}}
"""

