    IERC4626 public vault;
    IERC20 public asset;

    function setUp() public {{
        address vaultAddr = {vault_address};
        address assetAddr = {asset_address};

        vault = IERC4626(vaultAddr);
        asset = IERC20(assetAddr);
        handler = new VaultHandler(vaultAddr, assetAddr);

        // Direct invariant testing solely to handler
        targetContract(address(handler));
    }}

    /// @notice Invariant 1: Vault Underlying Asset Solvency
    /// The physical token balance held by the vault must cover totalAssets recorded.
    function invariant_vault_solvency() public view {{
        uint256 physicalBalance = asset.balanceOf(address(vault));
        uint256 recordedAssets = vault.totalAssets();
        assertGe(
            physicalBalance,
            recordedAssets,
            "INVARIANT_VIOLATION: Vault is insolvent (physical assets < recorded totalAssets)"
        );
    }}

    /// @notice Invariant 2: First-Depositor / Share Price Inflation Resistance
    /// Deposits of non-zero assets must never result in 0 minted shares.
    function invariant_no_zero_shares_dilution() public view {{
        assertEq(
            handler.ghost_zero_share_deposits_count(),
            0,
            "INVARIANT_VIOLATION: Depositor was completely diluted to 0 shares due to share price inflation"
        );
    }}

    /// @notice Invariant 3: Economic Extraction Objective
    /// An unprivileged attacker cannot achieve positive net marked-to-market extraction.
    function invariant_no_economic_extraction() public view {{
        address attacker = handler.actorAttacker();
        uint256 attackerCurrentAssetBal = asset.balanceOf(attacker);
        uint256 attackerShares = vault.balanceOf(attacker);
        uint256 attackerClaimable = vault.convertToAssets(attackerShares);

        uint256 initialAssets = handler.ghost_attacker_initial_assets();
        uint256 totalCurrentWealth = attackerCurrentAssetBal + attackerClaimable;

        // Attacker net wealth must not exceed initial capital + legitimate returns
        assertLe(
            totalCurrentWealth,
            initialAssets + 1 wei,
            "INVARIANT_VIOLATION: Unprivileged attacker extracted net value through sequence manipulation"
        );
    }}
}}
"""

