"""
Selective Symbolic Verifier (Halmos Integration):
Performs bounded symbolic execution for mathematical and authorization properties
where random fuzzing struggles (e.g., share rounding bias, conversion monotonicity, narrow access predicates).

Reports structured records:
Property checked | Input assumptions | Loop/call bounds | Dependency models | Solver outcome | Unexplored behavior
"""

import os
import shutil
import subprocess
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Any, Optional, List


@dataclass
class SymbolicVerificationRecord:
    property_checked: str
    target_contract: str
    input_assumptions: List[str]
    loop_call_bounds: str
    dependency_models: str
    solver_outcome: str  # PROVEN, COUNTEREXAMPLE, TIMEOUT, UNKNOWN, SOLVER_NOT_INSTALLED
    counterexample: Optional[Dict[str, Any]] = None
    unexplored_behavior: str = "None within declared bounds"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "property_checked": self.property_checked,
            "target_contract": self.target_contract,
            "input_assumptions": self.input_assumptions,
            "loop_call_bounds": self.loop_call_bounds,
            "dependency_models": self.dependency_models,
            "solver_outcome": self.solver_outcome,
            "counterexample": self.counterexample,
            "unexplored_behavior": self.unexplored_behavior
        }


class SymbolicVerifier:
    """Generates and executes Halmos symbolic verification contracts."""

    def __init__(self):
        self.halmos_bin = shutil.which("halmos")

    @staticmethod
    def generate_vault_symbolic_contract(
        vault_address: str,
        asset_address: str,
        vault_name: str = "TargetVault"
    ) -> str:
        return f"""// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";

interface IERC4626 {{
    function convertToShares(uint256 assets) external view returns (uint256);
    function convertToAssets(uint256 shares) external view returns (uint256);
    function previewDeposit(uint256 assets) external view returns (uint256);
    function previewRedeem(uint256 shares) external view returns (uint256);
    function totalAssets() external view returns (uint256);
    function totalSupply() external view returns (uint256);
}}

/**
 * @title VaultSymbolicChecks (Halmos)
 * @notice Bounded symbolic proof of ERC-4626 rounding direction and conversion properties.
 */
contract VaultSymbolicChecks is Test {{
    IERC4626 public immutable vault;

    constructor() {{
        vault = IERC4626({vault_address});
    }}

    /// @notice Symbolic Check 1: Round-trip asset conversion does not manufacture assets
    /// convertToAssets(convertToShares(assets)) <= assets
    function check_convert_round_trip_assets(uint256 assets) public view {{
        vm.assume(assets > 0 && assets < 1e30);
        uint256 shares = vault.convertToShares(assets);
        uint256 backToAssets = vault.convertToAssets(shares);
        assertLe(
            backToAssets,
            assets,
            "SYMBOLIC_VIOLATION: convertToAssets(convertToShares(a)) exceeded input assets"
        );
    }}

    /// @notice Symbolic Check 2: Preview deposit rounds down or equals convertToShares
    function check_preview_deposit_rounding(uint256 assets) public view {{
        vm.assume(assets > 0 && assets < 1e30);
        uint256 preview = vault.previewDeposit(assets);
        uint256 converted = vault.convertToShares(assets);
        assertLe(
            preview,
            converted,
            "SYMBOLIC_VIOLATION: previewDeposit exceeded convertToShares"
        );
    }}

    /// @notice Symbolic Check 3: Zero assets converts to zero shares
    function check_zero_assets_zero_shares() public view {{
        uint256 shares = vault.convertToShares(0);
        assertEq(shares, 0, "SYMBOLIC_VIOLATION: 0 assets produced non-zero shares");
    }}
}}
"""

    @classmethod
    def emit_symbolic_suite(
        cls,
        output_dir: Path,
        vault_address: str,
        asset_address: str
    ) -> Path:
        output_dir.mkdir(parents=True, exist_ok=True)
        path = output_dir / "VaultSymbolicChecks.halmos.sol"
        code = cls.generate_vault_symbolic_contract(vault_address, asset_address)
        path.write_text(code)
        return path

    def verify_property(
        self,
        test_dir: Path,
        contract_name: str,
        check_function_name: str,
        target_contract: str,
        input_assumptions: List[str],
        loop_bound: int = 2
    ) -> SymbolicVerificationRecord:
        """Runs Halmos if installed, or produces the bounded symbolic specification record."""
        if not self.halmos_bin:
            return SymbolicVerificationRecord(
                property_checked=check_function_name,
                target_contract=target_contract,
                input_assumptions=input_assumptions,
                loop_call_bounds=f"Unrolled loops up to {loop_bound}; bounded recursion",
                dependency_models="Mocked state or pinned static environment",
                solver_outcome="SOLVER_NOT_INSTALLED",
                unexplored_behavior="Z3/Halmos binary not present in local PATH; executable in CI"
            )

        cmd = [
            self.halmos_bin,
            "--function", check_function_name,
            "--loop", str(loop_bound)
        ]

        try:
            res = subprocess.run(cmd, cwd=test_dir, capture_output=True, text=True, timeout=60)
            if res.returncode == 0:
                outcome = "PROVEN"
            elif "Counterexample" in res.stdout:
                outcome = "COUNTEREXAMPLE"
            else:
                outcome = "UNKNOWN"

            return SymbolicVerificationRecord(
                property_checked=check_function_name,
                target_contract=target_contract,
                input_assumptions=input_assumptions,
                loop_call_bounds=f"Bounded to {loop_bound} unrolls",
                dependency_models="SMT-LIB bitvector and array theory",
                solver_outcome=outcome,
                unexplored_behavior="Execution paths exceeding bounded loop depth"
            )
        except subprocess.TimeoutExpired:
            return SymbolicVerificationRecord(
                property_checked=check_function_name,
                target_contract=target_contract,
                input_assumptions=input_assumptions,
                loop_call_bounds=f"Bounded to {loop_bound} unrolls",
                dependency_models="SMT-LIB bitvector",
                solver_outcome="TIMEOUT",
                unexplored_behavior="Solver timed out after 60s"
            )
        except Exception as e:
            return SymbolicVerificationRecord(
                property_checked=check_function_name,
                target_contract=target_contract,
                input_assumptions=input_assumptions,
                loop_call_bounds=f"Bounded to {loop_bound} unrolls",
                dependency_models="SMT-LIB bitvector",
                solver_outcome="UNKNOWN",
                unexplored_behavior=str(e)
            )
