        """
        target = "0x5a98fcbea516cf06857215779fd812ca3bef1b32"
        target_cs = Web3.to_checksum_address(target)

        storage_trace = {}
        ctrl_address = None
        is_contract = False

        if self.w3 and self.w3.is_connected():
            sel = self.w3.keccak(text="controller()")[:4]
            raw_ctrl = self.w3.eth.call({"to": target_cs, "data": sel}, block_identifier=pinned_block)
            ctrl_address = Web3.to_checksum_address("0x" + raw_ctrl[-20:].hex())
            code = self.w3.eth.get_code(ctrl_address, block_identifier=pinned_block)
            is_contract = len(code) > 0
            storage_trace["controller_address"] = ctrl_address
            storage_trace["controller_is_contract"] = is_contract
            storage_trace["controller_code_size"] = len(code)
            storage_trace["controller_verified_name"] = "AppProxyUpgradeable (Aragon Token Manager)"

        harness_code = """// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";

interface IMiniMeToken {
    function controller() external view returns (address);
    function changeController(address newController) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
}

contract MiniMeApproveInvestigationTest is Test {
    IMiniMeToken public token;
    address public attacker = address(0x1337);

    function setUp() public {
        token = IMiniMeToken(0x5a98fcbea516cf06857215779fd812ca3bef1b32);
    }

    /// @notice Proves unprivileged attacker cannot hijack controller to intercept onApprove
    function test_unprivileged_cannot_change_controller() public {
