            p = output_dir / "MiniMeApproveInvestigation.t.sol"
            p.write_text(harness_code)
            harness_path = str(p)

        evidence = {
            "reachability": "approve() is callable by any user, but external call is strictly constrained to controller()",
            "state_feasibility": f"Live controller is {ctrl_address} (Aragon AppProxyUpgradeable), verified at block {pinned_block}",
