        }

        if self.w3 and self.w3.is_connected():
            # Slots: Slot 4 (_totalSupply), Slot 5 (_name), Slot 6 (_symbol)
            for slot_idx, var_name in [(4, "_totalSupply"), (5, "_name"), (6, "_symbol")]:
                slot_hex = hex(slot_idx)
